namespace SingletonDI.Generator.Emitters;

/// <summary>
/// Emits the SingletonInitializer class that provides public API for initialization.
/// </summary>
internal static class SingletonInitializerEmitter
{
    private const string Namespace = "DependencyManager.Generated";

    /// <summary>
    /// Generates the SingletonInitializer class source code.
    /// </summary>
    public static string Generate()
    {
        return $$"""
                 // <auto-generated/>
                 #nullable enable
                 
                 namespace {{Namespace}}
                 {
                     /// <summary>
                     /// Provides public API for initializing the singleton container.
                     /// Call InitializeAsync() at application startup before accessing any singletons.
                     /// </summary>
                     public static class SingletonDIInitializer
                     {
                         /// <summary>
                         /// Initializes all singleton instances asynchronously.
                         /// Singletons on the same dependency level are initialized in parallel.
                         /// </summary>
                         /// <returns>A task that completes when all singletons are initialized.</returns>
                         public static global::System.Threading.Tasks.Task InitializeAsync() =>
                             Internal.SingletonDIContainer.InitializeAsync();
                     }
                 }
                 """;
    }
}
